UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardXPDifficulty`=5, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=0, `RewardSpell`=1284417, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=4202496, `FlagsEx2`=524288, `QuestDescription`='Not all of the visions in this place were clear to us. Some of them were... strange.\n\nOne in particular seemed to revolve around an unfamiliar people: a people that we learned are the Amani trolls.\n\nThe magic used to create the painting, to pull the memories from the past, are tied to the haranir and those close to us. If there was no connection, the Zur\'ashar--who create the paintings--could not have recalled troll history.\n\nI can show you and Zul\'jan, and you can judge for yourselves.', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='Speak to Orweyna in the Den of Echoes.', `VerifiedBuild`=69497 WHERE `ID`=92901;
-- quest 92904: 15 stlpcov obnovenych z TDB (ContentTuningID, QuestInfoID, RewardBonusMoney, RewardArtifactXPDifficulty, RewardArtifactXPMultiplier, Flags, FlagsEx, QuestDescription...)
UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardBonusMoney`=0, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=4202496, `QuestDescription`='I have heard de story since I was a child! De Amani were outnumbered and still dey fought on! Dey claimed victory through sheer will!\n\nOrweyna says de visions cannot lie. Uncle thinks details of de battle could have been lost. Dey would question everything it means to be Amani.\n\n<Zul\'jan scowls.>\n\nI must find de truth of dis. Uncle says if anyone would know, it would be de loa. De loa have said nothing of dis before, but we must start somewhere.\n\nIt\'s time to go home.', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='Meet Zul\'jan at Talonstrike Terrace in Atal\'Aman.', `VerifiedBuild`=69497 WHERE `ID`=92904;
