UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardXPDifficulty`=3, `RewardMoneyDifficulty`=3, `RewardBonusMoney`=0, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=4202496, `QuestDescription`='My uncle has already started communin\' with de loa to find information on dis Ula\'tek. Meanwhile, we gonna dig through his boxes to see what we can find.\n\n<Zul\'jan points to all the boxes scattered around the terrace.>\n\nMy uncle has de biggest collection of histories among de Amani. I used to read through dem when I was a boy.\n\nLook for anything about Ula\'tek, snakes, or early Amani history. I\'ll take these, you search de others.', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='', `VerifiedBuild`=69497 WHERE `ID`=92907;
