UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardXPDifficulty`=6, `RewardMoneyDifficulty`=6, `RewardBonusMoney`=0, `RewardSpell`=1269447, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=4202496, `LogDescription`='Collect $1oa Vilebranch Scrolls from Maisara Deeps.', `QuestDescription`='De mask says we are lookin\' for de scrolls of Malacrass. While we are in Maisara, try to find any scrolls de Vilebranch have left around.\n\nMaisara is a dangerous place, so don\'t bother sortin\' through dem--just grab \'em and we can check later.\n\nEven if dey don\'t mention Ula\'tek, we might find information about their plans or intentions against de Amani.', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='Meet Loa Speaker Kinduru outside Maisara Deeps.', `VerifiedBuild`=69497 WHERE `ID`=92951;
