UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardBonusMoney`=0, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=4194304, `LogDescription`='Meet the Enchanted Amani Mask outside Maisara Deeps.', `QuestDescription`='De magic helped, but... not enough. I still don\'t remember my name or past life. Dat knowledge may be lost forever...\n\nI do remember more about Ula\'tek--or rather, where we might find more information!\n\nI was forced into dis form by de Vilebranch trolls. Dey kept dark knowledge secret from de other tribes, includin\' knowledge of Ula\'tek.\n\nIf we are to know more, we must go to de Maisara Deeps.', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='Meet the Enchanted Amani Mask outside Maisara Deeps.', `VerifiedBuild`=69497 WHERE `ID`=92952;
