UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardXPDifficulty`=6, `RewardMoneyDifficulty`=6, `RewardBonusMoney`=0, `RewardSpell`=1269447, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=8192, `QuestDescription`='While I was a servant of de Vilebranch, I remember discussions about Malacrass\'s research into Ula\'tek.\n\nMalacrass recorded his knowledge in scrolls that he kept with him. Now that he\'s dead, we need to find out what happened to dem.\n\nDe Vilebranch hex masters won\'t talk willingly... but if you slay dem, I can use their own necromantic magic against dem to compel dem to speak.', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='Meet Loa Speaker Kinduru outside Maisara Deeps.', `VerifiedBuild`=69497 WHERE `ID`=92953;
