UPDATE `world`.`quest_template` SET `ContentTuningID`=5071, `QuestInfoID`=81, `SuggestedGroupNum`=5, `RewardXPDifficulty`=8, `RewardMoneyDifficulty`=8, `RewardBonusMoney`=0, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=4202496, `PortraitGiver`=131548, `LogDescription`='Collect Malacrass\'s Notes from Vordaza and complete the Maisara Caverns dungeon.', `QuestDescription`='Malacrass\'s notes are with Vordaza, and she\'s using them to further her necromantic experiments.\n\nI need you to go into de Maisara Caverns to recover them. It will be dangerous, and you will need to gather allies before venturing in.\n\nI will stay here and protect my uncle. We need to sort through all de scrolls we gathered and see what else we can find out.', `AreaDescription`='', `PortraitGiverText`='Vordaza was Hex Lord Malacrass\'s favored apprentice. You believe she is in possession of Malacrass\'s notes.', `PortraitGiverName`='Vordaza', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='', `VerifiedBuild`=69497 WHERE `ID`=92954;
-- quest 92955: 15 stlpcov obnovenych z TDB (ContentTuningID, QuestInfoID, RewardBonusMoney, RewardArtifactXPDifficulty, RewardArtifactXPMultiplier, Flags, FlagsEx, QuestDescription...)
UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardBonusMoney`=0, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=4202496, `QuestDescription`='De ancestors did not bow to a loa--dey claimed a weapon! A weapon dat led to our victory.\n\nI must know more.\n\nYou said de tablets at Numazon are de oldest in Zul\'Aman. We can continue de search there. Perhaps de ancient Amani left behind clues for us.\n\nUncle says we should bring de mask. A stray memory might be de key to unlocking dis mystery.', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='Meet Zul\'jan at Numazon.', `VerifiedBuild`=69497 WHERE `ID`=92955;
-- quest 92957: 18 stlpcov obnovenych z TDB (ContentTuningID, QuestInfoID, RewardXPDifficulty, RewardMoneyDifficulty, RewardBonusMoney, RewardArtifactXPDifficulty, RewardArtifactXPMultiplier, Flags...)
UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardXPDifficulty`=5, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=0, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=4202496, `LogDescription`='Take $1oa rubbings of the Ancient Amani Tablets within Numazon.', `QuestDescription`='If de tablets were made when de Amani first arrived in Zul\'Aman, den there must be some clue about Ula\'tek here.\n\nDe tablets are too heavy to carry, so Uncle suggested dat we take rubbings of de inscriptions.\n\nI scouted ahead and gathered a few, but I ran into de Vilebranch. I came back here to make sure Uncle was safe.\n\nEnter Numazon and collect more of de rubbings while I watch over Uncle. Watch out for de Vilebranch.', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='', `VerifiedBuild`=69497 WHERE `ID`=92957;
-- quest 92958: 19 stlpcov obnovenych z TDB (ContentTuningID, QuestInfoID, RewardXPDifficulty, RewardMoneyDifficulty, RewardBonusMoney, RewardSpell, RewardArtifactXPDifficulty, RewardArtifactXPMultiplier...)
UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardXPDifficulty`=5, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=0, `RewardSpell`=1269197, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=4202496, `LogDescription`='Collect $1oa Vilebranch Hex Fetishes from the Vilebranch trolls in Numazon.', `QuestDescription`='I wish I could be more help but... de gaps in my memory. Due to de damage de mask has sustained, dat magic has leaked out for who knows how long.\n\nYou repaired de physical parts of de mask, but de magic within is still weak.\n\nZul\'jan says Vilebranch trolls occupy this crypt. De magic dat binds me together is like de magic they use.\n\nYou might be able to help. Retrieve their hex fetishes--I should be able to drain the magic from them.', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='', `VerifiedBuild`=69497 WHERE `ID`=92958;
-- quest 93010: 15 stlpcov obnovenych z TDB (ContentTuningID, QuestInfoID, RewardBonusMoney, RewardArtifactXPDifficulty, RewardArtifactXPMultiplier, Flags, FlagsEx, QuestDescription...)
UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardBonusMoney`=0, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=4202496, `QuestDescription`='Here! De note says Ula\'tek was sealed away by de Amani. To break de seal, one needs a \"key.\"\n\n<Zul\'jan flips through the notes.>\n\nDe key was hidden within a shrine and protected with ancient magic. But which shrine... \n\n<Zul\'jan looks up.>\n\nDidn\'t de tablets at Numazon mention a shrine bein\' \"dedicated to de serpent\'s victory?\" We know from de visions in Harandar dat Ula\'tek was a serpent. \n\nDat must be it! De key is hidden at de serpent shrine in Atal\'Aman!', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='Meet Zul\'jan at the Warlord\'s Stair within Atal\'Aman.', `VerifiedBuild`=69497 WHERE `ID`=93010;
-- quest 93011: 17 stlpcov obnovenych z TDB (ContentTuningID, QuestInfoID, RewardXPDifficulty, RewardMoneyDifficulty, RewardBonusMoney, RewardArtifactXPDifficulty, RewardArtifactXPMultiplier, Flags...)
UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardXPDifficulty`=6, `RewardMoneyDifficulty`=6, `RewardBonusMoney`=0, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=577765384, `FlagsEx`=4202496, `QuestDescription`='If Malacrass was right, de key to Ula\'tek should be right here.\n\n<Zul\'jan\'s heavy hammer thumps onto the shrine for emphasis.>\n\nIt may take me some time to break through de stone to find it.\n\nI don\'t know what kind of protection de ancestors have in place, but you will have to deal with dem while I work.\n\nI admit, I did not believe de visions in Harandar. I don\'t fully trust Malacrass\'s notes either.\n\nBut if de key is here, dat would be undeniable proof dat what we are chasing is real.', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='Speak to Orweyna in Amani\'Zar Village.', `VerifiedBuild`=69497 WHERE `ID`=93011;
-- quest 93012: 19 stlpcov obnovenych z TDB (ContentTuningID, QuestInfoID, RewardXPDifficulty, RewardMoneyDifficulty, RewardBonusMoney, RewardSpell, RewardArtifactXPDifficulty, RewardArtifactXPMultiplier...)
UPDATE `world`.`quest_template` SET `ContentTuningID`=5855, `QuestInfoID`=0, `RewardXPDifficulty`=6, `RewardMoneyDifficulty`=6, `RewardBonusMoney`=0, `RewardSpell`=1281585, `RewardArtifactXPDifficulty`=0, `RewardArtifactXPMultiplier`=1.0e0, `Flags`=40894472, `FlagsEx`=4194304, `FlagsEx2`=524288, `QuestDescription`='After the meeting in Harandar, I came here to speak with Zul\'jarra about the vision you witnessed. Zul\'jan had seemed upset when you left and it was not my intent to make him so.\n\nBut all of that can wait. Now that you\'re awake, you should go speak to Zul\'jarra. She wants to know what happened at Atal\'Aman.', `AreaDescription`='', `PortraitGiverText`='', `PortraitGiverName`='', `PortraitTurnInText`='', `PortraitTurnInName`='', `QuestCompletionLog`='Speak to Zul\'jarra at Amani\'Zar Village.', `VerifiedBuild`=69497 WHERE `ID`=93012;
