INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (92901, 'Amani history, painted on the walls of our ancestors. This magic does not work without a bond between our peoples.');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (92904, 'Why is my uncle so disorganized?');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (92907, 'Did you hear what it said? A weapon!');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (92951, '<Kinduru takes the bundle of scrolls. He says nothing, but is clearly concerned.>');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (92952, 'Malacrass is dead, but dat doesn\'t mean his knowledge is lost.');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (92953, 'The Maisara Caverns are even more dangerous than de Deeps, and Vordaza is as deadly as she is cruel.');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (92954, 'You got dem. Now let\'s see if dis was worth all de effort.\n\n<Zul\'jan flips through the scrolls.>');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (92955, 'Uncle does not understand. Ula\'tek could change everything.');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (92957, 'Look here! Dis mentions the Amani summoning a great serpent to save dem from a terrible foe.\n\nAnd here, de serpent was victorious but de Amani sealed it away.\n\nDe first shrine built in Atal\'Aman was dedicated to the serpent.\n\n<Kinduru continues to analyze the rubbings.>');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (92958, 'It will just take a moment to drain de magic from de fetishes.');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (93010, 'Dis shrine is ancient. Small. Unremarkable.\n\nDe perfect hiding place.');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (93011, 'The Amani found you and Kinduru at Atal\'Aman. They carried you back here.');
INSERT INTO `world`.`quest_offer_reward` (`ID`, `RewardText`) VALUES (93012, 'I have already sent scouts to search for Zul\'jan, but it will be impossible to cover so much ground. I pray he sees through de lies dat Malacrass has woven before it\'s too late.\n\n<Zul\'jarra\'s expression is grim, then softens as a small eagle lands on your shoulder.>\n\nThank you, <name>, for telling me what happened and for being with my uncle at de end.\n\nDis eagle was my uncle\'s favorite companion on his walks through Zul\'Aman. I think he would like it if you took care of him now dat he\'s gone.');
